const body = $input.first().json.body || $input.first().json;
const telegram_id = String(body.telegram_id || '').trim();
const operation = String(body.operation || '').trim();
if (!telegram_id) return [{ json: { error: 'No telegram_id — cannot identify user. This is a system error.' } }];
if (!operation) return [{ json: { error: 'Missing operation' } }];
return [{ json: { ...body, telegram_id, operation } }];

// Route to correct Gmail operation
const body = $('Extract & Validate').first().json;
const access_token = $input.first().json.access_token;
const op = body.operation;

// Build the Gmail API request params based on operation
let method = 'GET';
let urlPath = '';
let requestBody = null;

if (op === 'messages.list') {
  const q = encodeURIComponent(body.query || '');
  const max = body.maxResults || 10;
  urlPath = `https://gmail.googleapis.com/gmail/v1/users/me/messages?q=${q}&maxResults=${max}`;
} else if (op === 'messages.get') {
  urlPath = `https://gmail.googleapis.com/gmail/v1/users/me/messages/${body.messageId}?format=full`;
} else if (op === 'threads.get') {
  urlPath = `https://gmail.googleapis.com/gmail/v1/users/me/threads/${body.threadId}?format=full`;
} else if (op === 'messages.send' || op === 'messages.send-reply') {
  method = 'POST';
  urlPath = `https://gmail.googleapis.com/gmail/v1/users/me/messages/send`;
  const toAddr = body.to || '';
  const subject = body.subject || '';
  const bodyText = body.body || '';
  const cc = body.cc ? `Cc: ${body.cc}\r\n` : '';
  const replyTo = body.replyTo ? `In-Reply-To: ${body.replyTo}\r\nReferences: ${body.replyTo}\r\n` : '';
  const rawMsg = `To: ${toAddr}\r\nSubject: ${subject}\r\n${cc}${replyTo}Content-Type: text/plain; charset=utf-8\r\n\r\n${bodyText}`;
  const encoded = Buffer.from(rawMsg).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
  requestBody = JSON.stringify({ raw: encoded });
} else {
  throw new Error(`Unknown Gmail operation: ${op}`);
}

return [{ json: { method, urlPath, requestBody, access_token } }];
